// Lee el CSV subido en el formulario y registra cada fila con las mismas reglas que la web:
//   1. Pregunta a la API si el libro ya existe (mismo título, autor y género).
//   2. Si existe, le suma los ejemplares; si no, lo crea.
// Las filas se procesan en orden, así que un libro repetido dentro del CSV se suma al creado.
const api = $('Configuración').first().json.apiUrl.replace(/\/+$/, '');

// Resultado del flujo: los datos (visibles en las ejecuciones) y la página que ve quien subió el archivo.
// n8n inserta `pagina` dentro de su propia página de cierre, así que es un fragmento con estilos en línea.
function resultado(resumen, lineas, cuentas) {
  const esc = (t) => String(t).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const color = (l) => (l.includes('ERROR') ? '#b91c1c' : l.includes('Ojo:') ? '#92400e' : '#1f2937');
  const pagina = `<div style="padding:24px 16px">
<div style="max-width:640px;margin:0 auto;background:#fff;border:1px solid #dbdfe7;border-radius:8px;padding:24px;font-size:14px">
<h1 style="font-size:20px;font-weight:600;margin:0 0 8px;color:#1f2937">Importación terminada</h1>
<p style="font-size:15px;margin:0 0 16px;color:#1e3a8a"><strong>${esc(resumen)}</strong></p>
<ul style="padding-left:18px;margin:0">${lineas.map((l) => `<li style="margin:6px 0;color:${color(l)}">${esc(l)}</li>`).join('')}</ul>
<p style="margin:20px 0 0"><a href="/form/importar-libros" style="color:#1e3a8a">Importar otro archivo</a></p>
</div></div>`;
  return [{ json: { resumen, detalle: lineas.join('\n'), ...cuentas, pagina } }];
}

// --- Lectura del CSV ---------------------------------------------------------------------
const campo = Object.keys($input.first().binary ?? {})[0];
if (!campo) return resultado('No se recibió ningún archivo.', [], { creados: 0, actualizados: 0, errores: 1 });

const contenido = (await this.helpers.getBinaryDataBuffer(0, campo)).toString('utf8').replace(/^﻿/, '');
const primeraLinea = contenido.split(/\r?\n/, 1)[0];
// Excel en español guarda los CSV con «;»; el resto, con «,».
const separador = (primeraLinea.match(/;/g) ?? []).length > (primeraLinea.match(/,/g) ?? []).length ? ';' : ',';

function leerCsv(texto, sep) {
  const filas = [];
  let fila = [], valor = '', entreComillas = false;
  for (let i = 0; i < texto.length; i++) {
    const c = texto[i];
    if (entreComillas) {
      if (c === '"' && texto[i + 1] === '"') { valor += '"'; i++; }
      else if (c === '"') entreComillas = false;
      else valor += c;
    } else if (c === '"') entreComillas = true;
    else if (c === sep) { fila.push(valor); valor = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && texto[i + 1] === '\n') i++;
      fila.push(valor); filas.push(fila); fila = []; valor = '';
    } else valor += c;
  }
  if (valor !== '' || fila.length) { fila.push(valor); filas.push(fila); }
  return filas;
}

const [cabecera = [], ...filas] = leerCsv(contenido, separador);
const normalizar = (s) => s.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z]/g, '');
const ALIAS = {
  title: ['titulo', 'title', 'libro'],
  author: ['autor', 'autora', 'author'],
  genre: ['genero', 'genre', 'categoria'],
  copies: ['ejemplares', 'copias', 'cantidad', 'unidades', 'copies', 'totalcopies'],
};
const columna = {};
cabecera.forEach((nombre, i) => {
  const n = normalizar(nombre);
  for (const [clave, alias] of Object.entries(ALIAS)) if (alias.includes(n) && columna[clave] === undefined) columna[clave] = i;
});
const faltan = ['title', 'author', 'genre'].filter((c) => columna[c] === undefined);
if (faltan.length) {
  const nombres = { title: 'titulo', author: 'autor', genre: 'genero' };
  return resultado(
    `Al archivo le faltan columnas obligatorias: ${faltan.map((c) => nombres[c]).join(', ')}.`,
    [`Cabecera encontrada: ${cabecera.join(' | ') || '(vacía)'}`,
      `La primera fila debe ser: titulo${separador}autor${separador}genero${separador}ejemplares`],
    { creados: 0, actualizados: 0, errores: 1 });
}

// --- Llamadas a la API -------------------------------------------------------------------
const llamar = async (method, ruta, opciones = {}) => {
  const r = await this.helpers.httpRequest({
    method, url: `${api}${ruta}`, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, ...opciones,
  });
  if (r.statusCode >= 400) {
    const cuerpo = r.body ?? {};
    const campos = cuerpo.fields ? Object.values(cuerpo.fields).join('; ') : '';
    throw new Error(campos || cuerpo.message || `La API respondió ${r.statusCode}`);
  }
  return r.body;
};

const lineas = [];
let creados = 0, actualizados = 0, errores = 0;
for (const [i, fila] of filas.entries()) {
  const numero = i + 2; // +1 por la cabecera y +1 porque las hojas de cálculo cuentan desde 1
  const celda = (clave) => (columna[clave] === undefined ? '' : (fila[columna[clave]] ?? '').trim());
  const libro = { title: celda('title'), author: celda('author'), genre: celda('genre') };
  if (!libro.title && !libro.author && !libro.genre) continue; // fila vacía

  const textoEjemplares = celda('copies');
  const ejemplares = textoEjemplares === '' ? 1 : Number(textoEjemplares);
  try {
    if (!Number.isInteger(ejemplares) || ejemplares < 1 || ejemplares > 1000) {
      throw new Error(`«${textoEjemplares}» no es un número de ejemplares válido (de 1 a 1000)`);
    }
    if (!libro.title || !libro.author || !libro.genre) throw new Error('faltan el título, el autor o el género');

    const duplicado = await llamar('GET', '/books/duplicates', { qs: libro });
    if (duplicado.sameBook) {
      const actualizado = await llamar('POST', `/books/${duplicado.sameBook.id}/copies`, { body: { quantity: ejemplares } });
      actualizados++;
      const sumados = ejemplares === 1 ? 'se sumó 1 ejemplar' : `se sumaron ${ejemplares} ejemplares`;
      lineas.push(`Fila ${numero}: «${libro.title}» ya existía; ${sumados} (ahora tiene ${actualizado.totalCopies}).`);
    } else {
      await llamar('POST', '/books', { body: { ...libro, totalCopies: ejemplares } });
      creados++;
      const otros = (duplicado.differentGenre ?? []).map((l) => l.genre);
      const nota = otros.length ? ` Ojo: ya existía con otro género (${otros.join(', ')}).` : '';
      lineas.push(`Fila ${numero}: «${libro.title}» creado con ${ejemplares} ${ejemplares === 1 ? 'ejemplar' : 'ejemplares'}.${nota}`);
    }
  } catch (e) {
    errores++;
    lineas.push(`Fila ${numero}: ERROR en «${libro.title || '(sin título)'}»: ${e.message}`);
  }
}

const partes = [
  `${creados} ${creados === 1 ? 'libro nuevo' : 'libros nuevos'}`,
  `${actualizados} con ejemplares sumados`,
  `${errores} ${errores === 1 ? 'fila con error' : 'filas con error'}`,
];
return resultado(lineas.length ? partes.join(' · ') : 'El archivo no tiene filas con libros.', lineas,
  { creados, actualizados, errores });
